function renderAnalytics(){
  const ritRows=currentRit(),rit=calcRit(ritRows),routes=calcRitByRoute(ritRows),days=calcRitByDay(ritRows).slice().sort((a,b)=>a.date.localeCompare(b.date));
  const workDays=days.filter(x=>(Number(x.count)||0)>0).length,avg=workDays?rit.count/workDays:0,top=routes[0]||null;
  const finAll=calcFin(currentFin()),finOut=calcFin(currentFinExpense()),sav=calcSav();
  const mealRows=currentMeal(),mealCount=mealRows.reduce((n,x)=>n+(Number(x.count)||0),0),mealMoney=mealRows.reduce((n,x)=>n+(Number(x.total)||0),0);
  $('anAvgRit').textContent=workDays?`${avg.toFixed(avg%1?1:0)} Rit`:'0 Rit';
  $('anTopRoute').textContent=top?top.route:'—';
  $('anTopRouteSub').textContent=top?`${top.count} ritase • ${rp(top.money)}`:'Belum ada data';
  $('anExpense').textContent=rp(finOut.out);
  $('anMealCount').textContent=`${mealCount}×`;
  $('anMealMoney').textContent=rp(mealMoney);
  $('anRitTotal').textContent=`${rit.count} Rit`;
  const latest=days.slice(-7),max=Math.max(1,...latest.map(x=>Number(x.count)||0));
  $('anRitBars').innerHTML=latest.length?latest.map(x=>{const d=parseYmdLocal(x.date),label=d?new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short'}).format(d):x.date;const pct=Math.max(8,Math.round(((Number(x.count)||0)/max)*100));return `<div class="analytics-bar-item"><div class="analytics-bar-value">${x.count}</div><div class="analytics-bar-track"><i style="height:${pct}%"></i></div><small>${esc(label)}</small></div>`}).join(''):'<div class="analytics-empty">Belum ada data Ritase untuk ditampilkan.</div>';
  const insights=[];
  if(top)insights.push({tone:'blue',icon:'↗',text:`Route paling sering: ${top.route} dengan ${top.count} ritase pada periode ini.`});
  else insights.push({tone:'muted',icon:'•',text:'Belum ada Ritase pada periode aktif.'});
  if(workDays)insights.push({tone:'cyan',icon:'≈',text:`Rata-rata ${avg.toFixed(1)} ritase per hari kerja dari ${workDays} hari aktif.`});
  const ratio=finAll.inc>0?(finOut.out/finAll.inc)*100:null;
  if(ratio!==null)insights.push({tone:ratio>100?'coral':'green',icon:'Rp',text:`Pengeluaran periode ini setara ${Math.round(ratio)}% dari total pemasukan berjalan.`});
  else insights.push({tone:'muted',icon:'Rp',text:`Pengeluaran periode ini ${rp(finOut.out)}; belum ada pemasukan untuk dibandingkan.`});
  const target=Math.max(0,Number(state.settings.target)||0);
  if(target>0){const pct=Math.max(0,Math.round((sav.balance/target)*100));insights.push({tone:pct>=100?'green':'amber',icon:'◎',text:pct>=100?`Target Tabungan sudah tercapai ${pct}%.`:`Progress Tabungan ${pct}% menuju target ${rp(target)}.`});}
  if(mealCount>0)insights.push({tone:'amber',icon:'⌁',text:`Kasbon aktif setelah reset manual: ${mealCount}× dengan total ${rp(mealMoney)}.`});
  $('anInsights').innerHTML=insights.slice(0,5).map(x=>`<div class="analytics-insight ${x.tone}"><span>${esc(x.icon)}</span><p>${esc(x.text)}</p></div>`).join('');
}
// Absensi stores the chosen work shift without altering the legacy calendar date/payroll period.
function absWorkDate(when,shift){const d=new Date(when);if(shift==='malam'&&d.getHours()<6)d.setDate(d.getDate()-1);return ymd(d)}
function selectedAbsForWork(when=now()){
 const t=new Date(when),h=t.getHours(),current=ymd(t),prior=new Date(t);prior.setDate(prior.getDate()-1);
 const allowed=h<6?[current,ymd(prior)]:[current];
 return state.abs.filter(x=>x&&['siang','malam'].includes(x.shift)&&allowed.includes(x.workDate||x.date))
  .sort((a,b)=>String(b.iso||'').localeCompare(String(a.iso||'')))[0]||null;
}
