// The Ritase quick list follows working shifts, not midnight calendar dates.
// 06:00-18:00 = Siang; 18:00-06:00 next day = Malam (local device time).
function ritaseActiveShiftWindow(value){
 const t=new Date(value),h=t.getHours(),day=ymd(t);
 const start=new Date(t.getFullYear(),t.getMonth(),t.getDate(),h<6?18:h<18?6:18);
 if(h<6)start.setDate(start.getDate()-1);
 let end=new Date(start.getTime());end.setHours(end.getHours()+12);
 let overtime=false,afterOvertime=false;
 if(h>=18&&isDayOvertimeForDate(day)){
  start.setHours(6,0,0,0);end=new Date(t.getFullYear(),t.getMonth(),t.getDate()+1,0,0,0,0);overtime=true;
 }else if(h<6){
  const previous=new Date(t);previous.setDate(previous.getDate()-1);
  if(isDayOvertimeForDate(ymd(previous))){start.setTime(new Date(t.getFullYear(),t.getMonth(),t.getDate(),0,0,0,0).getTime());afterOvertime=true}
 }
 return{start,end,key:`${start.getTime()}-${end.getTime()}-${overtime?'ot':afterOvertime?'post':'normal'}`,shift:overtime||h>=6&&h<18?'siang':'malam',overtime,afterOvertime};
}
