function renderSav(){const all=calcSav(),s=calcSav(currentSav()),rows=currentSav().slice().sort((a,b)=>b.iso.localeCompare(a.iso));$('savBalance').textContent=rp(all.balance);$('savBorrowed').textContent=rp(all.borrowed);$('savTargetDisplay').textContent=rp(state.settings.target);$('savProgress').textContent=rp(s.ret);const target=Math.max(0,Number(state.settings.target)||0),pct=target>0?Math.min(100,Math.max(0,(all.balance/target)*100)):0;$('savProgressPct').textContent=target>0?`${Math.round(pct)}%`:'0%';$('savProgressText').textContent=target>0?`${rp(all.balance)} dari ${rp(target)}`:'Target belum diatur';$('savProgressFill').style.width=`${pct}%`;$('savProgressFill').classList.toggle('target-reached',target>0&&all.balance>=target);$('savSummary').textContent=`Periode ${monthName(activePeriod())}: Setoran ${rp(s.dep)} • Pengambilan ${rp(s.wd)} • Pengembalian ${rp(s.ret)} • Saldo tabungan berjalan ${rp(all.balance)} • Belum kembali ${rp(all.borrowed)}`;$('savList').innerHTML=rows.map(x=>{const tone=x.type==='deposit'?'sav-item-deposit':x.type==='withdraw'?'sav-item-withdraw':'sav-item-return';const label=x.type==='deposit'?'+ Setor':x.type==='withdraw'?'- Ambil':'+ Kembalikan';return `<div class="item sav-item ${tone}"><div class="sav-item-head"><span class="sav-type-badge">${label}</span><strong>${rp(x.amount)}</strong></div><div class="item-meta">${esc(x.dateText)} • ${esc(x.time)}${x.note?' • '+esc(x.note):''}</div></div>`}).join('')||'<div class="summary">Belum ada transaksi tabungan pada periode ini.</div>';renderDashboard()}
function renderFin(){const rows=currentFin().slice().sort((a,b)=>b.iso.localeCompare(a.iso)),f=calcFin(rows),fOut=calcFin(currentFinExpense()),today=ymd(now()),todayRows=rows.filter(x=>x.date===today);const bal=(f.balance<0?'- ':'')+rp(Math.abs(f.balance));$('finSummary').innerHTML=`<div class="fin-summary-pro"><div class="fin-summary-cell fin-sum-income"><span>Pemasukan</span><strong>${rp(f.inc)}</strong><small>Akumulatif</small></div><div class="fin-summary-cell fin-sum-expense"><span>Pengeluaran</span><strong>${rp(fOut.out)}</strong><small>Periode aktif</small></div><div class="fin-summary-cell fin-sum-balance ${f.balance<0?'is-negative':'is-positive'}"><span>Saldo Berjalan</span><strong>${bal}</strong><small>Semua transaksi</small></div></div><div class="rit-summary-note">Daftar di bawah hanya menampilkan transaksi Keuangan hari ini. Riwayat tanggal sebelumnya tetap tersimpan di Riwayat dan Laporan.</div>`;$('finList').innerHTML=todayRows.map(x=>`<div class="item fin-item ${x.type==='in'?'fin-item-income':'fin-item-expense'}"><div class="fin-item-head"><span class="fin-type-badge">${x.type==='in'?'Pemasukan':'Pengeluaran'}</span><strong>${x.type==='in'?'+ ':'- '}${rp(x.amount)}</strong></div><div class="item-meta">${esc(x.dateText)} • ${esc(x.time)}${x.note?' • '+esc(x.note):''}</div></div>`).join('')||'<div class="summary">Belum ada transaksi Keuangan hari ini.</div>'}
function allPeriods(){const set=new Set([activePeriod(),activeRitPeriod(),activeMealPeriod(),...state.abs.map(x=>x.period),...state.rit.map(x=>x.period),...state.sav.map(x=>x.period),...state.fin.map(x=>x.period),...state.meal.map(x=>x.period)]);return [...set].sort().reverse()}
let historyRenderLimit=100;const HISTORY_RENDER_STEP=100;
function renderHistory(){
  const ps=allPeriods(),sel=$('historyMonth').value||ps[0];
  $('historyMonth').innerHTML=ps.map(p=>`<option value="${p}" ${p===sel?'selected':''}>${monthName(p)}${state.archives.includes(p)?' • Arsip':''}</option>`).join('');
  const p=$('historyMonth').value,term=$('searchText').value.trim().toLowerCase(),cat=$('searchCat').value;
  let rows=[];
  state.abs.filter(x=>x.period===p).forEach(x=>rows.push({cat:'abs',activityIso:x.iso||'',status:x.status,title:`Absensi • ${x.status}`,meta:`${x.dateText} • ${x.time}${x.note?' • '+x.note:''}`,search:`absensi ${x.status} ${x.dateText} ${x.time} ${x.note||''}`}));
  state.rit.filter(x=>x.period===p).forEach(x=>rows.push({cat:'rit',activityIso:x.inputIso||x.iso||'',title:`Ritase • ${x.route}`,meta:`${x.workDate} • ${x.shift} • ${x.count} ritase • ${rp(x.total)} • Input ${x.inputDateText} ${x.inputTime}${x.note?' • '+x.note:''}`,search:`ritase ${x.route} ${x.workDate} ${x.shift} ${x.count} ${x.total} ${x.inputDateText} ${x.inputTime} ${x.note||''}`}));
  state.sav.filter(x=>x.period===p).forEach(x=>rows.push({cat:'sav',activityIso:x.iso||'',title:`Tabungan • ${x.type==='deposit'?'Setor':x.type==='withdraw'?'Ambil':'Kembalikan'} ${rp(x.amount)}`,meta:`${x.dateText} • ${x.time}${x.note?' • '+x.note:''}`,search:`tabungan ${x.type} ${x.amount} ${x.dateText} ${x.time} ${x.note||''}`}));
  state.fin.filter(x=>x.period===p).forEach(x=>rows.push({cat:'fin',activityIso:x.iso||'',finType:x.type,title:`Keuangan • ${x.type==='in'?'Pemasukan':'Pengeluaran'} ${rp(x.amount)}`,meta:`${x.dateText} • ${x.time}${x.note?' • '+x.note:''}`,search:`keuangan ${x.type} ${x.amount} ${x.dateText} ${x.time} ${x.note||''}`}));
  state.meal.filter(x=>x.period===p).forEach(x=>rows.push({cat:'meal',activityIso:x.iso||'',title:`Kasbon Makan • ${x.count}× = ${rp(x.total)}`,meta:`${x.dateText} • ${x.time} • ${rp(Number(x.rate??x.snapshot?.mealRate??state.settings.mealRate??10000))}/1`,search:`kasbon makan ${x.count} ${x.total} ${x.dateText} ${x.time}`}));
  if(cat!=='all')rows=rows.filter(x=>x.cat===cat);
  if(term)rows=rows.filter(x=>(x.title+' '+x.meta+' '+x.search).toLowerCase().includes(term));
  rows.sort((a,b)=>String(b.activityIso||'').localeCompare(String(a.activityIso||'')));
  const totalRows=rows.length,shownRows=rows.slice(0,historyRenderLimit);
  const shownNote=totalRows>shownRows.length?` • menampilkan ${shownRows.length}`:'';
  $('historySummary').innerHTML=`<span class="history-count">${totalRows}</span> data ditemukan untuk <strong>${esc(monthName(p))}</strong>${shownNote}.`;
  $('historyResults').innerHTML=shownRows.map(x=>{
    const statusClass=x.cat==='abs'&&x.status?' history-abs-'+String(x.status).toLowerCase():'';
    const finClass=x.cat==='fin'&&x.finType?' history-fin-'+(x.finType==='in'?'income':'expense'):'';
    const catLabel=x.cat==='abs'?'Absensi':x.cat==='rit'?'Ritase':x.cat==='sav'?'Tabungan':x.cat==='fin'?'Keuangan':'Kasbon';
    return `<div class="item search-result history-${esc(x.cat)}${statusClass}${finClass}"><div class="history-rail"><span class="history-dot"></span></div><div class="history-content"><div class="history-topline"><span class="history-cat">${catLabel}</span><span class="history-title">${esc(x.title.replace(/^.*? • /,''))}</span></div><div class="item-meta">${esc(x.meta)}</div></div></div>`;
  }).join('')||'<div class="history-empty"><div class="history-empty-icon">⌕</div><div class="history-empty-title">Tidak ada data</div><div class="history-empty-sub">Coba ubah kata pencarian, menu, atau periode.</div></div>';
  const more=$('historyLoadMore');
  if(more){
    const remaining=Math.max(0,totalRows-shownRows.length);
    more.classList.toggle('hidden',remaining===0);
    if(remaining)more.textContent=`Muat ${Math.min(HISTORY_RENDER_STEP,remaining)} Lagi • ${remaining} tersisa`;
  }
}
function updateMealCalc(){const c=Math.max(1,num($('mealCount').value)||1),rate=Math.max(0,Number(state.settings.mealRate)||0);$('mealCount').value=String(c);$('mealCalc').textContent=rp(c*rate);$('mealRate').textContent=`${c} × ${rp(rate)}`}
