function buildReportData(){
 const a=calcAbs(currentAbs()),ritRows=currentRit(),r=calcRit(ritRows),routes=calcRitByRoute(ritRows),days=calcRitByDay(ritRows),sAll=calcSav(),fAll=calcFin(currentFin()),fExp=calcFin(currentFinExpense()),mealRows=currentMeal();
 const mealCount=mealRows.reduce((n,x)=>n+(Number(x.count)||0),0),mealMoney=mealRows.reduce((n,x)=>n+(Number(x.total)||0),0);
 const top=routes[0]||null,avg=days.length?r.count/days.length:0;
 return {a,r,routes,days,sAll,fAll,fExp,mealCount,mealMoney,top,avg};
}
function renderReport(){const d=buildReportData();
 $('reportPeriod').textContent=`${monthName(activePeriod())} • ${ritPeriodRange(activePeriod())}`;
 $('reportAbs').textContent=`${d.a.Hadir} hari`; $('reportAbsMoney').textContent=rp(d.a.total);
 $('reportRit').textContent=`${d.r.count} Rit`; $('reportRitMoney').textContent=rp(d.r.money);
 $('reportSav').textContent=rp(d.sAll.balance); $('reportSavTarget').textContent=`Target ${rp(state.settings.target||0)}`;
 $('reportExpense').textContent=rp(d.fExp.out); $('reportIncome').textContent=`Pemasukan ${rp(d.fAll.inc)}`;
 $('reportAbsDetail').innerHTML=[reportLine('Hadir',d.a.Hadir+' hari'),reportLine('Overshift',d.a.Overshift+'×'),reportLine('Lembur',d.a.Lembur+'×'),reportLine('Izin / Sakit / Libur',`${d.a.Izin} / ${d.a.Sakit} / ${d.a.Libur}`),reportLine('Nilai Absensi',rp(d.a.total))].join('');
 const routeLines=d.routes.slice(0,5).map((x,i)=>reportLine(`#${i+1} ${x.route}`,`${x.count} Rit`,rp(x.money))).join('');
 $('reportRitDetail').innerHTML=reportLine('Total Ritase',d.r.count+' Rit',rp(d.r.money))+reportLine('Rata-rata / hari',`${d.avg.toFixed(1)} Rit`,`${d.days.length} hari kerja`)+(routeLines||reportLine('Route','Belum ada data'));
 $('reportMealDetail').innerHTML=reportLine('Periode Kasbon',`${mealPeriodRange(activeMealPeriod())}`)+reportLine('Sejak reset manual',`${d.mealCount} Kasbon`,rp(d.mealMoney));
 const balance=d.fAll.balance,progress=state.settings.target>0?Math.min(999,Math.round((d.sAll.balance/state.settings.target)*100)):0;
 const insights=[];
 insights.push(d.top?`Route terbanyak: ${d.top.route} (${d.top.count} Rit).`:'Belum ada data route pada periode aktif.');
 insights.push(`Rata-rata Ritase ${d.avg.toFixed(1)} per hari kerja.`);
 insights.push(`Saldo Keuangan berjalan ${balance<0?'- ':''}${rp(Math.abs(balance))}.`);
 if(state.settings.target>0)insights.push(`Progress Tabungan sekitar ${progress}% dari target.`);
 insights.push(`Kasbon aktif ${d.mealCount} kali senilai ${rp(d.mealMoney)}.`);
 $('reportInsight').innerHTML=insights.map((x,i)=>reportLine(`Insight ${i+1}`,x)).join('');
}
function buildReportText(){const d=buildReportData(),routes=d.routes.slice(0,5).map((x,i)=>`${i+1}. ${x.route}: ${x.count} Rit • ${rp(x.money)}`).join('\n')||'- Belum ada route';return `PTM — LAPORAN PERIODE\n${monthName(activePeriod())} • ${ritPeriodRange(activePeriod())}\n\nABSENSI\nHadir: ${d.a.Hadir} hari\nOvershift: ${d.a.Overshift}x\nLembur: ${d.a.Lembur}x\nIzin/Sakit/Libur: ${d.a.Izin}/${d.a.Sakit}/${d.a.Libur}\nNilai Absensi: ${rp(d.a.total)}\n\nRITASE\nTotal: ${d.r.count} Rit\nNilai: ${rp(d.r.money)}\nRata-rata: ${d.avg.toFixed(1)} Rit/hari\n${routes}\n\nTABUNGAN\nSaldo: ${rp(d.sAll.balance)}\nTarget: ${rp(state.settings.target||0)}\n\nKEUANGAN\nPemasukan berjalan: ${rp(d.fAll.inc)}\nPengeluaran periode: ${rp(d.fExp.out)}\nSaldo berjalan: ${d.fAll.balance<0?'- ':''}${rp(Math.abs(d.fAll.balance))}\n\nKASBON MAKAN\nPeriode: ${mealPeriodRange(activeMealPeriod())}\nKasbon aktif: ${d.mealCount}x\nTotal: ${rp(d.mealMoney)}`}

