function setMealDateOffset(days){const d=now();d.setDate(d.getDate()+days);const v=ymd(d);if(![...$('mealDate').options].some(o=>o.value===v))populateMealDates();$('mealDate').value=v}
function setMealTimeNow(){const d=now();$('mealTime').value=`${pad(d.getHours())}:${pad(d.getMinutes())}`}
function populateRitDates(){const sel=$('ritDate'),keep=sel.value||ymd(now());let html='';for(let i=0;i<=180;i++){const d=now();d.setDate(d.getDate()-i);const val=ymd(d),label=new Intl.DateTimeFormat('id-ID',{weekday:'short',day:'2-digit',month:'short',year:'numeric'}).format(d);html+=`<option value="${val}">${label}${i===0?' • Hari Ini':i===1?' • Kemarin':''}</option>`;}sel.innerHTML=html;if([...sel.options].some(o=>o.value===keep))sel.value=keep;}
function setRitDateOffset(days){const d=now();d.setDate(d.getDate()+days);const v=ymd(d);if(![...$('ritDate').options].some(o=>o.value===v))populateRitDates();$('ritDate').value=v}
let lastLiveDay=ymd(now());function tick(){const d=now(),day=ymd(d),shiftKey=ritaseActiveShiftWindow(d).key;$('liveDate').textContent=dateLong(d);$('liveTime').textContent=timeLong(d);if(day!==lastLiveDay){lastLiveDay=day;populateRitDates();populateMealDates();renderMeal();renderFin();renderDashboard();renderAnalytics();renderReport();syncAbsShiftDefault();syncRitShiftFromAbs();}if(shiftKey!==lastLiveRitShift){lastLiveRitShift=shiftKey;renderRit();}}
let lastLiveRitShift="";let clockTimer=0;function startClock(){tick();clearInterval(clockTimer);clockTimer=setInterval(tick,1000)}function stopClock(){clearInterval(clockTimer);clockTimer=0}startClock();document.addEventListener('visibilitychange',()=>document.hidden?stopClock():startClock());
if(location.protocol!=='file:'&&'serviceWorker' in navigator){
  window.addEventListener('load',async()=>{
    const el=document.getElementById('offlineState');
    try{
      const reg=await navigator.serviceWorker.register('sw.js',{scope:'./'});
      await navigator.serviceWorker.ready;
      const cache=await caches.open('ptm-ios-final-v2.1.0');
      const required=['index.html','styles.css','app.js','manifest.webmanifest'];
      const ok=(await Promise.all(required.map(x=>cache.match(x)))).every(Boolean);
      if(el){
        el.textContent=ok?'✓ Siap Offline — aman digunakan tanpa internet':'Mode offline sedang disiapkan. Tetap online sebentar lalu buka ulang aplikasi.';
      }
      if(!navigator.serviceWorker.controller){
        setTimeout(()=>location.reload(),700);
      }
    }catch(e){if(el)el.textContent='Mode offline belum aktif. Buka aplikasi sekali saat online lalu refresh.';}
  });
}else{const el=document.getElementById('offlineState');if(el){if(location.protocol==='file:'){el.textContent='✓ Siap Offline — aman digunakan tanpa internet';el.classList.add('offline-ready')}else{el.textContent='Mode offline PWA tidak tersedia di browser ini.';}}}
// v43: iOS native select picker can leave a visible focus halo after closing.
document.addEventListener('change',e=>{
  const el=e.target;
  if(el&&el.tagName==='SELECT')requestAnimationFrame(()=>el.blur());
},true);
let runtimeErrorToastAt=0;const runtimeErrorNotice=()=>{const t=Date.now();if(t-runtimeErrorToastAt<5000)return;runtimeErrorToastAt=t;showToast('Terjadi gangguan kecil. Data tetap dipertahankan; coba ulangi aksi terakhir.','error',3200)};window.addEventListener('error',e=>{console.error('PTM runtime error',e.error||e.message);runtimeErrorNotice()});window.addEventListener('unhandledrejection',e=>{console.error('PTM promise error',e.reason);runtimeErrorNotice()});
if($('copyReportBtn'))$('copyReportBtn').onclick=async()=>{const text=buildReportText();try{await navigator.clipboard.writeText(text);showToast('Ringkasan laporan disalin.','success')}catch(_){const ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();showToast('Ringkasan laporan disalin.','success')}};
if($('shareReportBtn'))$('shareReportBtn').onclick=async()=>{const text=buildReportText();if(navigator.share){try{await navigator.share({title:'PTM — Laporan Periode',text});return}catch(e){if(e&&e.name==='AbortError')return}}try{await navigator.clipboard.writeText(text);showToast('Perangkat tidak mendukung Share. Ringkasan disalin.','info',3000)}catch(_){showToast('Bagikan tidak tersedia. Gunakan Salin Teks.','warn',3000)}};
function csvCell(v){const x=String(v??'');return /[\",\n]/.test(x)?'"'+x.replace(/"/g,'""')+'"':x}
function buildReportCsv(){const d=buildReportData(),rows=[];const push=(bagian,item,nilai,detail='')=>rows.push([bagian,item,nilai,detail]);
push('Periode','Periode Utama',monthName(activePeriod()),ritPeriodRange(activePeriod()));
push('Absensi','Hadir',d.a.Hadir+' hari',rp(d.a.total));push('Absensi','Overshift',d.a.Overshift+'x');push('Absensi','Lembur',d.a.Lembur+'x');push('Absensi','Izin',d.a.Izin+' hari');push('Absensi','Sakit',d.a.Sakit+' hari');push('Absensi','Libur',d.a.Libur+' hari');push('Absensi','Nilai Absensi',rp(d.a.total));
push('Ritase','Total Ritase',d.r.count+' Rit',rp(d.r.money));push('Ritase','Rata-rata per hari',d.avg.toFixed(1)+' Rit',d.days.length+' hari kerja');d.routes.slice(0,10).forEach((x,i)=>push('Ritase','#'+(i+1)+' '+x.route,x.count+' Rit',rp(x.money)));
push('Tabungan','Saldo Tabungan',rp(d.sAll.balance));push('Tabungan','Target Tabungan',rp(state.settings.target||0));
push('Keuangan','Pemasukan',rp(d.fAll.inc));push('Keuangan','Pengeluaran Periode',rp(d.fExp.out));push('Keuangan','Saldo Berjalan',rp(d.fAll.balance));
push('Kasbon Makan','Periode Kasbon',mealPeriodRange(activeMealPeriod()));push('Kasbon Makan','Sejak Reset Manual',d.mealCount+' Kasbon',rp(d.mealMoney));
return '\ufeff'+[['Bagian','Item','Nilai','Detail'],...rows].map(r=>r.map(csvCell).join(',')).join('\n')}
function downloadTextFile(name,text,type){const blob=new Blob([text],{type:type||'text/plain;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1200)}
if($('csvReportBtn'))$('csvReportBtn').onclick=()=>{const name=`PTM-Laporan-${activePeriod()}.csv`;downloadTextFile(name,buildReportCsv(),'text/csv;charset=utf-8');showToast('Laporan CSV dibuat.','success',2400)};
if($('printReportBtn'))$('printReportBtn').onclick=()=>{renderReport();document.body.classList.add('print-report');requestAnimationFrame(()=>setTimeout(()=>{window.print();setTimeout(()=>document.body.classList.remove('print-report'),500)},60))};
window.addEventListener('afterprint',()=>document.body.classList.remove('print-report'));
